WITH flattened_attrs AS (SELECT id, plan, currency, tier_limits, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE currency = 'EUR') SELECT id, plan, currency, avg_tier_price, entry_price, LEAD(lowest_price, 2, 0) OVER (PARTITION BY plan ORDER BY avg_tier_price, id) AS next_lowest_price, AVG(avg_tier_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS avg_tier_price_avg_5, CUME_DIST() OVER (ORDER BY avg_tier_price DESC NULLS LAST) AS avg_tier_price_cume_dist FROM flattened_attrs WHERE avg_tier_price <= 27;
